const $=s=>document.querySelector(s);let catalog,selected,activeDailyTab='A';
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
const label=r=>catalog.config.schedules[r.kind].label;
const classification=x=>catalog.config.categories[x]||catalog.config.topics[x]||x;
function link(url,text){const a=el('a',text);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function download(r){const b=new Blob([r.markdown],{type:'text/markdown;charset=utf-8'}),u=URL.createObjectURL(b);const a=link(u,'전체 원고 내려받기');a.download=r.id+'.md';a.onclick=()=>setTimeout(()=>URL.revokeObjectURL(u),1000);return a;}
function issueSection(x,r){const section=el('section',undefined,'item');if(r.kind!=='daily')section.append(el('span',classification(x.classification),'badge'));if(x.journalId)section.append(el('span',x.journalId,'badge'));section.append(el('h3',x.title),el('p',x.summary),el('h4','왜 중요한가'),el('p',x.interpretation),el('p',`발생일 ${x.eventDate||'미확인'} · 연결 원문 ${x.sources.length}건`,'muted'));if(x.aiUse)section.append(el('p',`AI 활용 ${x.aiUse} · 확인 수준 ${x.evidenceLevel} · DOI ${x.doi||'미확인'}`,'muted'));
 const sources=el('div',undefined,'sources');for(const s of x.sources){const p=el('p');const level={body:'본문 확인',index:'검색 발견·본문 미확인',legacy:'이관 기록'}[s.readLevel]||'이관 기록';p.append(link(s.url,s.publisher+' 원문'),document.createTextNode(' · '+level+' · 게시 '+(s.publishedAt||s.publishedDate||'미확인')));sources.append(p);}section.append(sources);if(x.previousReports.length)section.append(el('p','관련 과거 회차: '+x.previousReports.join(', '),'muted'));if(x.alternatives.length){const det=el('details');det.append(el('summary','같은 사건의 추가 보도 '+x.alternatives.length+'건'));x.alternatives.forEach(a=>det.append(el('p',a.title+' — '+a.summary+' / '+a.interpretation)));section.append(det);}return section;}

function dailyTabs(r,d){const tabs=el('div',undefined,'domain-tabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','브리핑 분야');const panel=el('div',undefined,'domain-panel');const ids=Object.keys(catalog.config.categories);if(!ids.includes(activeDailyTab))activeDailyTab='A';
 const draw=()=>{panel.replaceChildren();const items=r.items.filter(x=>x.classification===activeDailyTab);panel.append(el('h3',`${activeDailyTab} · ${catalog.config.categories[activeDailyTab]}`,'domain-heading'));items.forEach(x=>panel.append(issueSection(x,r)));tabs.querySelectorAll('button').forEach(b=>{const on=b.dataset.domain===activeDailyTab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});};
 ids.forEach((id,index)=>{const count=r.items.filter(x=>x.classification===id).length,b=el('button',`${id} ${catalog.config.categories[id]} ${count}`,'domain-tab');b.type='button';b.dataset.domain=id;b.setAttribute('role','tab');b.onclick=()=>{activeDailyTab=id;draw();};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const next=(index+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length;tabs.children[next].focus();tabs.children[next].click();};tabs.append(b);});d.append(tabs,panel);draw();}
function show(r){selected=r.id;const d=$('#detail');d.replaceChildren(el('span',label(r),'badge'),el('span','검토 전 초안 · r'+r.revision,'badge'),el('h2',r.title));
 if(r.kind==='daily'){dailyTabs(r,d)}else{
  d.append(el('p','조사기간 '+r.window.from+' ~ '+r.window.to,'muted'),el('p','작성 '+r.generatedAt+' · 보관 '+r.storedAt,'muted'),download(r));
  const ul=el('ul');r.highlights.forEach(h=>ul.append(el('li',h)));d.append(ul);if(r.limitations.length)d.append(el('p',r.limitations.join(' / '),'warning'));
  if(r.statistics){const s=r.statistics;d.append(el('h3','수집 범위 내 논문 분포'),el('p',`중복 제거 ${s.total}편 · AI 활용 ${s.ai}편 / 전체 ${s.total}편 · AI 여부 미확인 ${s.unknown}편`));const t=el('table');for(const [k,v] of Object.entries(s.counts)){const row=el('tr');row.append(el('td',k),el('td',String(v)+'편'));t.append(row);}d.append(t);}
  r.items.forEach(x=>d.append(issueSection(x,r)));
 }
 const coverage=el('details');coverage.append(el('summary','출처별 조사 범위·접근 결과'));r.coverage.forEach(c=>coverage.append(el('p',`${c.sourceId} · ${c.status} · ${c.note}`)));d.append(coverage);
 const history=el('details');history.append(el('summary','이 보고서의 수정 이력'));catalog.reports.filter(p=>p.kind===r.kind&&p.cycle===r.cycle).forEach(p=>{const b=el('button',`r${p.revision} · ${p.generatedAt}`);b.onclick=()=>show(p);history.append(b);});d.append(history);const raw=el('details');raw.append(el('summary','보존한 원고 전체 보기'),el('pre',r.markdown));d.append(raw);
 document.querySelectorAll('.report').forEach(b=>b.classList.toggle('active',b.dataset.id===selected));}
function render(){const q=$('#query').value.trim().toLowerCase(),kind=$('#kind').value,c=$('#category').value,from=$('#from').value,to=$('#to').value;if(Object.hasOwn(catalog.config.categories,c))activeDailyTab=c;const seen=new Set();const latest=catalog.reports.filter(r=>{const k=r.kind+':'+r.cycle;if(!$('#history').checked&&seen.has(k))return false;seen.add(k);return true;});const rs=latest.filter(r=>(!kind||r.kind===kind)&&(!from||r.date>=from)&&(!to||r.date<=to)&&(!c||r.items.some(x=>x.classification===c))&&(!q||JSON.stringify([r.title,r.highlights,r.items]).toLowerCase().includes(q)));$('#status').textContent=`${rs.length}개 보고서 · ${$('#history').checked?'수정본 포함':'회차별 최신본'} · 검토 전 초안`;$('#reports').replaceChildren();rs.forEach(r=>{const b=el('button',undefined,'report');b.dataset.id=r.id;b.append(el('strong',label(r)),el('span',r.date+', '+r.items.length+'개 항목','muted'));b.onclick=()=>show(r);$('#reports').append(b);});if(rs.length){show(rs.find(r=>r.id===selected)||rs[0]);}else $('#detail').replaceChildren(el('h2','해당 보고서가 없습니다'),el('p','조건을 변경하거나 다음 예약 실행 결과를 확인해 주세요.'));}
async function init(){try{const response=await fetch('catalog.json',{cache:'no-store'});if(!response.ok)throw Error('목록 수신 실패');catalog=await response.json();for(const [k,s] of Object.entries(catalog.config.schedules)){const card=el('div',undefined,'card'),count=catalog.reports.filter(r=>r.kind===k).length;card.append(el('h2',s.label),el('p',s.time),el('span',count?count+'개 저장본':'첫 보고서 대기','muted'));$('#schedule').append(card);}for(const [k,v] of [...Object.entries(catalog.config.categories),...Object.entries(catalog.config.topics),...catalog.config.paperCategories.map(x=>[x,x])]){const o=el('option',v);o.value=k;$('#category').append(o);}$('#scope').append(el('p','E-1: '+Object.values(catalog.config.topics).join(' · ')),el('p','E-2: '+catalog.config.paperCategories.join(' · ')),el('p','대표 주제 1개/논문. AI 활용 여부는 yes/no/unknown의 별도 태그. 접근 실패 자료는 0편으로 간주하지 않으며, 확인한 자료의 분포만 표시합니다.'));catalog.config.journals.forEach(j=>{const p=el('p');p.append(document.createTextNode(j.id+' · '),link(j.discoveryUrl,j.name));$('#scope').append(p);});$('#scope').append(el('p',catalog.config.journalLinkStatus,'muted'));$('#built').textContent='아카이브 구성 '+catalog.builtAt;for(const s of ['#kind','#category','#query','#from','#to','#history'])$(s).addEventListener('input',render);render();}catch(e){$('#status').textContent='자료를 불러오지 못했습니다. 연결 상태를 확인해 주세요.';}}
init();
